"""
title: VMware Private AI Services Pipe (Improved)
author: VMware / Enhanced by AI Assistant
author_url: https://github.com
funding_url: https://github.com/open-webui
version: 0.1.7
requirements: httpx, openai
"""

from pydantic import BaseModel, Field
from loguru import logger
from typing import Union, Generator, Iterator, cast
import httpx
import openai
import os


class Pipe:
    class Valves(BaseModel):
        PAIS_API_BASE_URL: str = Field(
            # default="https://pais.pse.lab/api/v1/compatibility/openai/v1",
            default="https://r169-env4-pais-api.pse.lab/api/v1/compatibility/openai/v1",
            description="Override base URL for PAIS API endpoints.",
        )
        PAIS_API_KEY: str = Field(
            default="vcfa:pais:mYcxkKyjXgNDTJyiDNfYo88jCXF33XYb",
            description="Required API key to retrieve the model list.",
        )
        ENABLE_STREAMING: bool = Field(
            default=True,
            description="Enable streaming of chat completion. Defaults to True.",
        )
        CONNECTION_TIMEOUT: float = Field(
            default=10.0,
            description="Timeout for establishing connection (seconds). Default: 10s",
        )
        READ_TIMEOUT: float = Field(
            default=300.0,
            description="Timeout for reading response (seconds). Default: 300s (5 min)",
        )
        SHOW_THINKING_STATUS: bool = Field(
            default=True,
            description="Show 'Model is thinking...' status updates. Default: True",
        )
        RESPONSE_MAX_TOKENS: int = Field(
            default=256,
            description="Maximum number of tokens to generate in the response. Default: 256",
        )
        pass

    def __init__(self):
        self.type = "manifold"
        self.valves = self.Valves()
        pass

    def citation_generator(self, all_contexts: list) -> Generator[dict, None, None]:
        """Generate citation events from context information"""
        for context_info in all_contexts:
            yield {
                "event": {
                    "type": "citation",
                    "data": {
                        "document": [context_info["text"]],
                        "text": context_info["text"],
                        "metadata": [context_info["metadata"]],
                        "distances": [context_info["metadata"]["score"]],
                        "source": {
                            "name": context_info["metadata"]["origin_name"],
                            "url": context_info["metadata"]["origin_ref"],
                        },
                    },
                }
            }

    def get_base_url(self):
        """Get the base URL from valves or environment"""
        if not self.valves.PAIS_API_BASE_URL == "":
            return self.valves.PAIS_API_BASE_URL
        else:
            return os.environ.get("OPENAI_API_BASE_URL")

    def get_all_assistants(self):
        """Fetch all available assistants from PAIS API"""
        base_url = self.get_base_url()
        assistants_url = f"{base_url}/assistants?limit=400"

        # Use reasonable timeout for listing assistants
        timeout = httpx.Timeout(
            connect=self.valves.CONNECTION_TIMEOUT,
            read=30.0,  # Listing should be quick
            write=10.0,
            pool=10.0,
        )
        headers = {}
        headers["Authorization"] = f"Bearer {self.valves.PAIS_API_KEY}"
        headers["Content-Type"] = "application/json"

        try:
            with httpx.Client(verify=False, timeout=timeout, headers=headers) as client:
                response = client.get(assistants_url)

                if response.status_code == 200:
                    assistants = response.json()
                    return assistants.get("data")
                else:
                    logger.error(
                        f"Failed to retrieve assistants. Status code: {response.status_code}"
                    )
                    return [
                        {
                            "id": "error",
                            "name": "Could not fetch models from PAIS, please check your API key and API Base URL and try again",
                        }
                    ]
        except httpx.TimeoutException as e:
            logger.error(f"Timeout while fetching assistants: {e}")
            return [
                {
                    "id": "error",
                    "name": "Timeout while fetching models from PAIS. Please check your connection.",
                }
            ]
        except Exception as e:
            logger.error(f"Error fetching assistants: {e}")
            return [
                {
                    "id": "error",
                    "name": f"Error fetching models: {str(e)}",
                }
            ]

    def get_assistant(self, assistant_id):
        """Get a specific assistant by ID"""
        for assistant in self.assistants:
            if assistant.get("id") == assistant_id:
                return assistant
        return None

    def pipes(self):
        """Return list of available assistants/pipes"""
        assistants = self.get_all_assistants()
        self.assistants = assistants
        return self.assistants

    async def pipe(
        self, body: dict, __user__: dict, __event_emitter__=None
    ) -> Union[str, Generator, Iterator]:
        """
        Main pipe function that handles chat completions

        Args:
            body: Request body containing messages, model, etc.
            __user__: User information
            __event_emitter__: Optional event emitter for status updates
        """

        # Extract target assistant
        target_id = body["model"][body["model"].find(".") + 1 :]
        target_assistant = self.get_assistant(target_id)

        if not target_assistant:
            return "Error: Could not find the requested assistant/model."

        # Configure timeout with separate connection and read timeouts
        timeout = httpx.Timeout(
            connect=self.valves.CONNECTION_TIMEOUT,
            read=self.valves.READ_TIMEOUT,
            write=30.0,
            pool=10.0,
        )

        headers = {}
        headers["Authorization"] = f"Bearer {self.valves.PAIS_API_KEY}"
        headers["Content-Type"] = "application/json"
        extra_body = {"x-pais-max-iterations": 50}
        http_client = httpx.Client(verify=False, timeout=timeout)
        base_url = self.get_base_url()
        agents_url = f"{base_url}/agents/{target_assistant['id']}"

        openai_client_completions = openai.OpenAI(
            base_url=agents_url,
            api_key=self.valves.PAIS_API_KEY,
            http_client=http_client,
        )

        try:
            # Emit "thinking" status if enabled
            if self.valves.SHOW_THINKING_STATUS and __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": "Connecting to AI model...",
                            "done": False,
                        },
                    }
                )

            # Make the API request
            r = openai_client_completions.chat.completions.create(
                model=f"{target_assistant['model']}",
                messages=body.get("messages", []),
                stream=self.valves.ENABLE_STREAMING,
                temperature=body.get("temperature", 0),
                max_tokens=body.get("max_tokens", self.valves.RESPONSE_MAX_TOKENS),
            )

            if self.valves.ENABLE_STREAMING:
                return self.stream_generator(r, __event_emitter__, http_client)
            else:
                return self.non_stream_response(r, __event_emitter__, http_client)

        except openai.APITimeoutError as e:
            http_client.close()
            error_msg = (
                f"Request timed out after {self.valves.READ_TIMEOUT} seconds. "
                f"The model may need more time to process your request. "
                f"Try: 1) Increase the READ_TIMEOUT in settings, "
                f"2) Simplify your query, or 3) Try again later."
            )
            logger.error(f"Timeout Error: {e}")
            return f"Error: {error_msg}"
        except openai.APIConnectionError as e:
            http_client.close()
            error_msg = (
                f"Could not connect to the AI service. "
                f"Please check: 1) Your network connection, "
                f"2) The PAIS_API_BASE_URL is correct, "
                f"3) The service is running."
            )
            logger.error(f"Connection Error: {e}")
            return f"Error: {error_msg}"
        except openai.RateLimitError as e:
            http_client.close()
            return f"Error: Rate Limit Exceeded - Too many requests. Please wait a moment and try again. Details: {e}"
        except openai.AuthenticationError as e:
            http_client.close()
            return f"Error: Authentication Failed - Please check your PAIS_API_KEY is correct. Details: {e}"
        except openai.BadRequestError as e:
            http_client.close()
            return f"Error: Bad Request - The request was invalid. This might be due to unsupported parameters or malformed input. Details: {e}"
        except openai.APIStatusError as e:
            http_client.close()
            return f"Error: API Status Error - Status {e.status_code}, Response: {e.response.text if e.response else 'N/A'}"
        except Exception as e:
            http_client.close()
            logger.error(f"Unexpected error: {e}")
            return f"Error: An unexpected error occurred: {str(e)}"

    async def stream_generator(self, r, __event_emitter__=None, http_client=None):
        """
        Generator for streaming responses with status updates

        Args:
            r: OpenAI streaming response
            __event_emitter__: Optional event emitter for status updates
            http_client: HTTP client to close after streaming completes
        """
        all_contexts = []
        first_token_received = False
        thinking_status_shown = False

        try:
            # Show "thinking" status before first token
            if self.valves.SHOW_THINKING_STATUS and __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {"description": "Model is thinking...", "done": False},
                    }
                )
                thinking_status_shown = True

            for chunk in r:
                # Handle content chunks
                logger.debug(f"chunk: {chunk}")
                if chunk.choices:
                    delta_content = chunk.choices[0].delta.content
                    if delta_content:
                        # Clear thinking status on first token
                        if (
                            not first_token_received
                            and thinking_status_shown
                            and __event_emitter__
                        ):
                            await __event_emitter__(
                                {
                                    "type": "status",
                                    "data": {
                                        "description": "Generating response...",
                                        "done": True,
                                    },
                                }
                            )
                            first_token_received = True

                        yield delta_content

                # Handle context/citation information
                if chunk.index_context_info:
                    # Show status that we're retrieving knowledge
                    if __event_emitter__ and not all_contexts:
                        await __event_emitter__(
                            {
                                "type": "status",
                                "data": {
                                    "description": "Retrieving relevant knowledge...",
                                    "done": False,
                                },
                            }
                        )

                    for context_info in chunk.index_context_info:
                        all_contexts.append(context_info)

            # Clear any remaining status
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {"description": "Complete", "done": True},
                    }
                )

            # Yield all citations at the end
            for citation in self.citation_generator(all_contexts):
                yield citation

        except Exception as e:
            logger.error(f"Error in stream_generator: {e}")
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {"description": f"Error: {str(e)}", "done": True},
                    }
                )
            yield f"\n\nError during streaming: {str(e)}"
        finally:
            # Close HTTP client after streaming is complete
            if http_client:
                http_client.close()

    async def non_stream_response(self, r, __event_emitter__=None, http_client=None):
        """
        Generator for non-streaming responses

        Args:
            r: OpenAI response
            __event_emitter__: Optional event emitter for status updates
            http_client: HTTP client to close after response completes
        """
        try:
            # Show processing status
            if self.valves.SHOW_THINKING_STATUS and __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": "Processing response...",
                            "done": False,
                        },
                    }
                )

            # Yield the content
            yield r.choices[0].message.content

            # Clear status
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {"description": "Complete", "done": True},
                    }
                )

            # Yield citations
            all_contexts = cast(list, r.index_context_info)
            for citation in self.citation_generator(all_contexts):
                yield citation

        except Exception as e:
            logger.error(f"Error in non_stream_response: {e}")
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {"description": f"Error: {str(e)}", "done": True},
                    }
                )
            yield f"\n\nError: {str(e)}"
        finally:
            # Close HTTP client after response is complete
            if http_client:
                http_client.close()
